S = {'mode': 'rev', 't0': None, 'n': 0}
def control(obs):
    t = obs['t']
    st = obs['status']
    v = obs['motion']['v_mps']
    hold = obs['motion'].get('hold_s', 0.0)
    h = obs.get('hitch_deg', 0.0)
    ry = obs['rig']['trailer_rear'][1]
    if S['mode'] == 'rev':
        if st in ('PINNED', 'JACKKNIFED') and hold <= 0 and abs(v) < 0.05:
            S['mode'] = 'fwd'
            S['t0'] = t
            S['n'] += 1
        else:
            e = ry + 0.6
            hd = max(-6.0, min(6.0, -8.0 * e))
            steer = 3.0 * (h - hd)
            steer = max(-34.0, min(34.0, steer))
            return (steer, -0.3)
    el = t - S['t0']
    if el < 2.5:
        return (0.0, 0.4)
    S['mode'] = 'rev'
    return (0.0, -0.3)

