    v = obs['motion']['v_mps']
    st = obs['status']
    hold = obs['motion'].get('hold_s', 0.0)
    h = obs.get('hitch_deg', 0.0)
    ry = obs['rig']['trailer_rear'][1]
    if S['ph'] == 'fwd':
        if S['t0'] is None:
            S['t0'] = t
        if t - S['t0'] < 1.5:
            return (-20.0, 0.3)
        S['ph'] = 'stop'
        return (0.0, 0.0)
    if S['ph'] == 'stop':
        if abs(v) < 0.05:
            S['ph'] = 'rev'
        return (0.0, 0.0)
