        S['ph'] = 'fwd'
        S['t0'] = None
        S['n'] += 1
        return (-20.0, 0.3)
    if v > 0.05:
        return (0.0, 0.0)
    steer = 2.0 * (h + 8.0) + 6.0 * (ry + 0.9)
