def control(obs):
    h = obs['hitch_deg']
    st = obs['status']
    views = obs.get('views') or {}
    cam = views.get('camera')
    if cam is None or st in ('PINNED', 'JACKKNIFED'):
        return (0.0, 0.0, -41)
    near = 99.0
    for b, d in cam.get('walls', []):
        near = min(near, d)
    for b, d in views.get('direct', {}).get('walls', []):
        if abs(b) < 25:
            near = min(near, d)
    if near < 1.0:
        return (0.0, 0.0, -41)
    steer = max(-12.0, min(12.0, 1.0 * h))
    return (steer, -0.08, -41)

